@page "/recipes/category/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Any())
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="text-warning mb-1">
                            @for (int i = 1; i <= 5; i++)
                            {
                                @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                            }
                            <span class="text-muted ms-2">(@recipe.AverageRating / 5 · @recipe.RatingCount ratings)</span>
                        </p>
                        <a href="/recipes/@recipe.Id" class="btn btn-primary mt-2">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <div class="alert alert-info">No recipes found in this category.</div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipes/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (Recipe is not null)
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/category/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">🧾 Ingredients</h5></div>
                <div class="card-body">
                    <ul class="list-unstyled">
                        @foreach (var ingredient in Recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                        {
                            <li>• @ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">👨‍🍳 Instructions</h5></div>
                <div class="card-body">
                    @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="card mt-4">
        <div class="card-body">
            <h5>Rate this Recipe</h5>
            <StarRating RecipeId="Recipe.Id" />
        </div>
    </div>
}
else
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-primary">Back to Home</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="fs-3" style="cursor: pointer; color: @(star <= SelectedRating ? "#ffc107" : "#dee2e6");"
              @onclick="() => Rate(star)">★</span>
    }

    @if (SelectedRating > 0)
    {
        <span class="ms-2 text-success">You rated this @SelectedRating/5 ✓</span>
    }
    else
    {
        <span class="ms-2 text-muted">Click to rate</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedRating { get; set; }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
    }
}

@page "/recipes/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe Submitted!</h4>
        <p>Your recipe "<strong>@Submission.Title</strong>" has been added to the community.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
    </div>
}
else
{
    <div class="card shadow-sm">
        <div class="card-body">
            <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
                <DataAnnotationsValidator />

                <div class="mb-3">
                    <label class="form-label" for="title">Recipe Title</label>
                    <InputText id="title" class="form-control" @bind-Value="Submission.Title"
                               placeholder="e.g., Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="category">Category</label>
                    <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                        <option value="">-- Select a category --</option>
                        @foreach (var cat in RecipeService.GetCategories())
                        {
                            <option value="@cat">@cat</option>
                        }
                        <option value="Other">Other</option>
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label class="form-label" for="ingredients">Ingredients</label>
                    <InputTextArea id="ingredients" class="form-control" rows="4"
                                   @bind-Value="Submission.Ingredients"
                                   placeholder="List ingredients separated by commas" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="steps">Steps</label>
                    <InputTextArea id="steps" class="form-control" rows="6"
                                   @bind-Value="Submission.Steps"
                                   placeholder="Write each step on a new line" />
                </div>

                <button type="submit" class="btn btn-success"
                        disabled="@(string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Ingredients))">
                    Submit Recipe
                </button>
            </EditForm>
        </div>
    </div>
}

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private bool Submitted { get; set; }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Submission.Title)) return;
        RecipeService.SubmitRecipe(Submission);
        Submitted = true;
    }
}

