<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe Submitted!</h4>
        <p>Your recipe "<strong>@Submission.Title</strong>" has been added to the community.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
    </div>
}
else
{
    <div class="card shadow-sm">
        <div class="card-body">
            <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
                <DataAnnotationsValidator />

                <div class="mb-3">
                    <label class="form-label" for="title">Recipe Title</label>
                    <InputText id="title" class="form-control" @bind-Value="Submission.Title"
                               placeholder="e.g., Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="category">Category</label>
                    <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                        <option value="">-- Select a category --</option>
                        @foreach (var cat in RecipeService.GetCategories())
                        {
                            <option value="@cat">@cat</option>
                        }
                        <option value="Other">Other</option>
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label class="form-label" for="ingredients">Ingredients</label>
                    <InputTextArea id="ingredients" class="form-control" rows="4"
                                   @bind-Value="Submission.Ingredients"
                                   placeholder="List ingredients separated by commas" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="steps">Steps</label>
                    <InputTextArea id="steps" class="form-control" rows="6"
                                   @bind-Value="Submission.Steps"
                                   placeholder="Write each step on a new line" />
                </div>

                <button type="submit" class="btn btn-success"
                        disabled="@(string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Ingredients))">
                    Submit Recipe
                </button>
            </EditForm>
        </div>
    </div>
}

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private bool Submitted { get; set; }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Submission.Title)) return;
        RecipeService.SubmitRecipe(Submission);
        Submitted = true;
    }
}
