@page "/"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Recipe Community</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">🍳 Recipe Community</h1>
    <p class="lead">Discover and share delicious recipes from around the world</p>
</div>

<h2 class="mb-4">Browse by Category</h2>
<div class="row">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 mb-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">@GetCategoryEmoji(category) @category</h3>
                    <p class="card-text text-muted">
                        @RecipeService.GetRecipesByCategory(category).Count recipe(s)
                    </p>
                    <a href="/recipes/category/@category" class="btn btn-outline-primary">
                        Browse Recipes
                    </a>
                </div>
            </div>
        </div>
    }
</div>

<div class="text-center mt-4">
    <a href="/recipes/submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
</div>

@code {
    private string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍕",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🍜",
        "Desserts" => "🍰",
        "Salads" => "🥗",
        _ => "🍽️"
    };
}

